-- Donjons : la difficulté devient une simple information (plus d'effet sur le combat) ; l'IV
-- par défaut des adversaires redevient un réglage unique (celui du niveau facile), et les niveaux,
-- PV du boss, temps et argent de chaque donjon livré sont fixés selon sa difficulté — uniquement là
-- où l'admin n'a rien modifié.
UPDATE "balance_settings" SET "data" = jsonb_set("data", '{dungeons}', ("data" -> 'dungeons') || jsonb_build_object('defaultOpponentIv', COALESCE(("data" #>> '{dungeons,difficulties,easy,opponentIv}')::int, 15), 'difficulties', jsonb_build_object('easy', jsonb_build_object('name', COALESCE("data" #>> '{dungeons,difficulties,easy,name}', 'Facile')), 'hard', jsonb_build_object('name', COALESCE("data" #>> '{dungeons,difficulties,hard,name}', 'Difficile')), 'veryHard', jsonb_build_object('name', COALESCE("data" #>> '{dungeons,difficulties,veryHard,name}', 'Très difficile')), 'extreme', jsonb_build_object('name', COALESCE("data" #>> '{dungeons,difficulties,extreme,name}', 'Extrême'))))) WHERE "data" ? 'dungeons' AND NOT ("data" -> 'dungeons' ? 'defaultOpponentIv');
--> statement-breakpoint
UPDATE "dungeons" SET "boss" = jsonb_set("boss", '{level}', '80'), "opponents" = '[{"speciesId":1,"formId":null,"level":65,"iv":null,"nature":null},{"speciesId":1,"formId":null,"level":68,"iv":null,"nature":null},{"speciesId":2,"formId":null,"level":71,"iv":null,"nature":null},{"speciesId":2,"formId":null,"level":74,"iv":null,"nature":null},{"speciesId":3,"formId":null,"level":77,"iv":null,"nature":null}]'::jsonb WHERE "id" = 'mega-florizarre' AND ("boss" ->> 'level')::int = 50 AND "opponents" = '[{"speciesId":1,"formId":null,"level":35,"iv":null,"nature":null},{"speciesId":1,"formId":null,"level":38,"iv":null,"nature":null},{"speciesId":2,"formId":null,"level":41,"iv":null,"nature":null},{"speciesId":2,"formId":null,"level":44,"iv":null,"nature":null},{"speciesId":3,"formId":null,"level":47,"iv":null,"nature":null}]'::jsonb;
--> statement-breakpoint
UPDATE "dungeons" SET "time_limit_seconds" = 240 WHERE "id" = 'mega-florizarre' AND "time_limit_seconds" = 180;
--> statement-breakpoint
UPDATE "dungeons" SET "money" = 8000 WHERE "id" = 'mega-florizarre' AND "money" = 5000;
